fn main() {
    let mut line = String::new();
    std::io::stdin().read_line(&mut line).unwrap();
    let n: i32 = line.trim().parse().unwrap();
    let text = String::from("Rust");
    println!("{} {}", text, n);
    println!("{}", text);
}

