fn create_label() -> String {
    String::from("安全返回")
}
fn main() {
    let label = create_label();
    println!("{}", label);
}

fn show_pair(left: &i32, right: &i32) {
    println!("{} {}", *left, *right);
}
fn main() {
    let value = 12;
    show_pair(&value, &value);
    println!("{}", value);
}

fn main() {
    let text = String::from("学习 Rust");
    let word = &text[7..]; // 两个汉字 6 字节，加一个空格
    println!("{}", word);
}

fn main() {
    let values = [10, 20, 30, 40];
    let window: &[i32] = &values[1..3];
    println!("{} {}", window[0], window.len());
}

fn show(text: &String) { println!("查看：{}", text); }
fn main() {
    let note = String::from("所有权保留");
    show(&note);
    println!("原值：{}", note);
}
